#pragma once
#include "kstationFlashStateTask.h"
namespace kstation {
class UiModeReadTask final {
public:enum class Stage{Field,ExtendWord,ExtendLong,Bind,Read,Return,Complete};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}uint8_t value()const{return value_;}unsigned nextClocks(const FlashCredits&c)const{return complete()?0:stage_==Stage::Bind?9:stage_==Stage::Read?3+c.read:stage_==Stage::Return?c.ret:3;}template<class R>unsigned advanceBefore(unsigned budget,const FlashCredits&c,R&&read){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;if(stage_==Stage::Read)value_=uint8_t(read());stage_=Stage(unsigned(stage_)+1);return cost;}
private:Stage stage_=Stage::Field;uint8_t value_=0;};
class UiSpecialModeTask final {
public:enum class Stage{Clear,ReadPage,ReadItem,Compare,SelectPage,Mode,SelectMode,Set,Test,Return,Complete};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool result()const{return page_==6&&item_==2&&mode_!=0;}bool awaiting()const{return waiting_;}void resume(uint8_t mode){mode_=mode;waiting_=false;}unsigned nextClocks(const FlashCredits&c)const{if(waiting_||complete())return 0;switch(stage_){case Stage::ReadPage:case Stage::ReadItem:return 9+c.read;case Stage::Compare:return 6;case Stage::Mode:return c.call;case Stage::Return:return c.ret;default:return 3;}}template<class R>unsigned advanceBefore(unsigned budget,const FlashCredits&c,R&&read){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::ReadPage:page_=uint8_t(read(true));break;case Stage::ReadItem:item_=uint8_t(read(false));break;case Stage::SelectPage:if(page_!=6||item_!=2)next=Stage::Test;break;case Stage::Mode:waiting_=true;break;case Stage::SelectMode:if(!mode_)next=Stage::Test;break;default:break;}stage_=next;return cost;}
private:Stage stage_=Stage::Clear;uint8_t page_=0,item_=0,mode_=0;bool waiting_=false;};
class UiQueueResetTask final {
public:enum class Stage{Keyboard,Adc,Panel,Return,Complete};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaiting()const{return waiting_;}void resume(){waiting_=false;}unsigned nextClocks(const FlashCredits&c)const{return waiting_||complete()?0:stage_==Stage::Return?c.ret:c.call;}unsigned advanceBefore(unsigned budget,const FlashCredits&c){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;if(stage_!=Stage::Return)waiting_=true;stage_=Stage(unsigned(stage_)+1);return cost;}
private:Stage stage_=Stage::Keyboard;bool waiting_=false;};
class UiPeriodicScanTask final {
public:enum class Stage{Tick,RetainTick,ReadStart,Elapsed,Compare,SelectDue,WriteStart,Keyboard,Adc,Encoder,Clock,Return,Complete};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaiting()const{return waiting_;}void resume(uint16_t tick=0){if(stage_==Stage::RetainTick)tick_=tick;waiting_=false;}unsigned nextClocks(const FlashCredits&c)const{if(waiting_||complete())return 0;switch(stage_){case Stage::Tick:case Stage::Keyboard:case Stage::Adc:case Stage::Encoder:case Stage::Clock:return c.call;case Stage::ReadStart:return 9+c.read;case Stage::Compare:return 6;case Stage::SelectDue:return 3;case Stage::WriteStart:return 9+c.write;case Stage::Return:return c.ret;default:return 3;}}template<class R,class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,R&&read,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::Tick:case Stage::Keyboard:case Stage::Adc:case Stage::Encoder:case Stage::Clock:waiting_=true;break;case Stage::ReadStart:start_=uint16_t(read());break;case Stage::SelectDue:if(uint16_t(tick_-start_)<25)next=Stage::Return;break;case Stage::WriteStart:write(tick_);break;default:break;}stage_=next;return cost;}
private:Stage stage_=Stage::Tick;uint16_t tick_=0,start_=0;bool waiting_=false;};
}
